export type User = { id: number; name: string };

function isUser(x: unknown): x is User {
  return typeof x === 'object' && x !== null
    && typeof (x as { id?: unknown }).id === 'number'
    && typeof (x as { name?: unknown }).name === 'string';
}

export function loadUsers(text: string): User[] {
  const data: unknown = JSON.parse(text);
  return Array.isArray(data) ? data.filter(isUser) : [];
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadUsers } from '../src/load.ts';

test('keeps valid users only', () => {
  const users = loadUsers('[{"id":1,"name":"An"},{"id":"x","name":"Bad"}]');
  assert.deepEqual(users, [{ id: 1, name: 'An' }]);
});

