export function groupBy(items: any[], keyFn: (item: any) => any): Map<any, any[]> {
  const groups = new Map<any, any[]>();
  for (const item of items) {
    const key = keyFn(item);
    const list = groups.get(key);
    if (list === undefined) groups.set(key, [item]); else list.push(item);
  }
  return groups;
}

import { groupBy } from '../src/group.ts';
type User = { id: number; role: 'STUDENT' | 'LECTURER' };
declare const users: User[];
const byRole = groupBy(users, (u) => u.role);     // Map<role, User[]> — no type args
const ids: number[] = (byRole.get('STUDENT') ?? []).map((u) => u.id);
export { ids };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { groupBy } from '../src/group.ts';

const users = [{ id: 1, role: 'A' }, { id: 2, role: 'B' }, { id: 3, role: 'A' }];
test('groupBy', () => {
  const g = groupBy(users, (u) => u.role);
  assert.deepEqual(g.get('A')?.map((u) => u.id), [1, 3]);
  assert.equal(g.get('C'), undefined);
});

